"""Generate a POSIX ``install.sh`` that falls back from global to domestic mirrors."""

from __future__ import annotations

import shlex

from .manifest import public_key_pem

TEMPLATE = r"""#!/bin/sh
# install.sh for __NAME__ __VERSION__ — generated by dokhaneh (https://github.com/mrzroot/dokhaneh)
#
# Tries the global source first, then falls back to domestic mirrors. Nothing is
# installed unless the manifest's Ed25519 signature AND the file's SHA-256 match.
#
# Environment overrides:
#   DOKHANEH_SOURCES      space-separated base URLs to try instead of the built-in list
#   DOKHANEH_ASSET        file to download (default: __ASSET__)
#   DOKHANEH_INSTALL_DIR  where to put the binary (default: /usr/local/bin, or ~/.local/bin)
#   DOKHANEH_OUT_DIR      where to save the verified file when no binary is configured (default: .)
#   DOKHANEH_TIMEOUT      connect timeout per source in seconds (default: 10)
set -eu

NAME=__Q_NAME__
VERSION=__Q_VERSION__
ASSET="${DOKHANEH_ASSET:-__Q_ASSET_RAW__}"
BINARY=__Q_BINARY__
SOURCES=__Q_SOURCES__
TIMEOUT="${DOKHANEH_TIMEOUT:-10}"
[ -n "${DOKHANEH_SOURCES:-}" ] && SOURCES="$DOKHANEH_SOURCES"

PUBKEY_PEM='__PEM__'

say()  { printf '%s\n' "dokhaneh: $*" >&2; }
die()  { say "error: $*"; exit 1; }
have() { command -v "$1" >/dev/null 2>&1; }

have openssl || die "openssl is required to verify the Ed25519 signature"
if have curl; then
  fetch() { curl -fsSL --connect-timeout "$TIMEOUT" --retry 2 -o "$2" "$1"; }
elif have wget; then
  fetch() { wget -q -T "$TIMEOUT" -t 2 -O "$2" "$1"; }
else
  die "curl or wget is required"
fi

sha256() {
  if have sha256sum; then sha256sum "$1" | awk '{print $1}'
  elif have shasum; then shasum -a 256 "$1" | awk '{print $1}'
  else openssl dgst -sha256 -r "$1" | awk '{print $1}'
  fi
}

TMP=$(mktemp -d 2>/dev/null || mktemp -d -t dokhaneh)
trap 'rm -rf "$TMP"' EXIT INT TERM
printf '%s\n' "$PUBKEY_PEM" > "$TMP/pub.pem"

verify_sig() {
  openssl base64 -d -A -in "$TMP/manifest.json.sig" -out "$TMP/sig.bin" 2>/dev/null || return 1
  openssl pkeyutl -verify -pubin -inkey "$TMP/pub.pem" -rawin \
    -in "$TMP/manifest.json" -sigfile "$TMP/sig.bin" >/dev/null 2>&1
}

OK=""
for SRC in $SOURCES; do
  SRC=${SRC%/}
  say "trying $SRC"
  rm -f "$TMP/manifest.json" "$TMP/manifest.json.sig" "$TMP/asset"
  if ! fetch "$SRC/manifest.json" "$TMP/manifest.json" || ! fetch "$SRC/manifest.json.sig" "$TMP/manifest.json.sig"; then
    say "  unreachable, next mirror"; continue
  fi
  if ! verify_sig; then say "  BAD SIGNATURE, skipping this mirror"; continue; fi
  if ! grep -qF "\"version\": \"$VERSION\"" "$TMP/manifest.json"; then
    say "  manifest is for a different version, skipping"; continue
  fi
  EXPECTED=$(grep -F "{\"name\": \"$ASSET\"," "$TMP/manifest.json" | sed 's/.*"sha256": "\([0-9a-f]*\)".*/\1/' | head -n 1)
  if [ -z "$EXPECTED" ]; then say "  $ASSET not listed in manifest"; continue; fi
  if ! fetch "$SRC/$ASSET" "$TMP/asset"; then say "  download failed, next mirror"; continue; fi
  ACTUAL=$(sha256 "$TMP/asset")
  if [ "$ACTUAL" != "$EXPECTED" ]; then say "  SHA-256 MISMATCH, skipping this mirror"; continue; fi
  say "  verified $ASSET (sha256 $ACTUAL)"
  OK=1; break
done
[ -n "$OK" ] || die "no mirror delivered a verified copy of $ASSET"

if [ -n "$BINARY" ]; then
  DEST="${DOKHANEH_INSTALL_DIR:-}"
  if [ -z "$DEST" ]; then
    if [ -w /usr/local/bin ]; then DEST=/usr/local/bin; else DEST="$HOME/.local/bin"; fi
  fi
  mkdir -p "$DEST" "$TMP/x"
  case "$ASSET" in
    *.tar.gz|*.tgz) tar -xzf "$TMP/asset" -C "$TMP/x" ;;
    *.zip) have unzip || die "unzip is required"; unzip -q "$TMP/asset" -d "$TMP/x" ;;
    *) cp "$TMP/asset" "$TMP/x/$BINARY" ;;
  esac
  BIN=$(find "$TMP/x" -type f -name "$BINARY" | head -n 1)
  [ -n "$BIN" ] || die "binary '$BINARY' not found in $ASSET"
  cp "$BIN" "$DEST/$BINARY" && chmod 755 "$DEST/$BINARY"
  say "installed $NAME $VERSION to $DEST/$BINARY"
else
  OUT="${DOKHANEH_OUT_DIR:-.}"
  mkdir -p "$OUT"
  cp "$TMP/asset" "$OUT/$ASSET"
  say "saved verified $ASSET to $OUT/"
fi
"""


def render_install_script(
    name: str,
    version: str,
    asset: str,
    sources: list[str],
    public_key_b64: str,
    binary: str | None = None,
) -> str:
    if not sources:
        raise ValueError("install.sh needs at least one source URL")
    pem = public_key_pem(public_key_b64).strip()
    q = shlex.quote
    out = TEMPLATE
    # Order matters: replace the longest placeholders first.
    for key, val in (
        ("__Q_ASSET_RAW__", asset.replace('"', "").replace("$", "").replace("`", "")),
        ("__Q_NAME__", q(name)),
        ("__Q_VERSION__", q(version)),
        ("__Q_BINARY__", q(binary or "")),
        ("__Q_SOURCES__", q(" ".join(sources))),
        ("__PEM__", pem),
        ("__NAME__", name.replace("\n", " ")),
        ("__VERSION__", version.replace("\n", " ")),
        ("__ASSET__", asset.replace("\n", " ")),
    ):
        out = out.replace(key, val)
    return out
